10: function isFiniteCoordinate(value: unknown): value is number {
11:   return typeof value === 'number' && Number.isFinite(value);
12: }
13: 
14: function asLonLat(value: unknown): [number, number] | null {
15:   if (!Array.isArray(value) || value.length < 2) return null;
16:   const [lon, lat] = value;
17:   if (!isFiniteCoordinate(lon) || !isFiniteCoordinate(lat)) return null;
18:   return [lon, lat];
19: }
