21: /**
22:  * The only coordinates a vehicle may be plotted at: a server-reported fix.
23:  *
24:  * Deliberately excludes corridor midpoints (dense route geometry) and any
25:  * hardcoded city fallback — a unit with no GPS ping has no location, and
26:  * inventing one is a lie that outranks any map dot. Exception: the middle of
27:  * an exactly-3-point `[prev, curr, next]` path triple. The backend's
28:  * invariant pass (telemetry_service) writes that triple with path[1] as the
29:  * unit's true current fix, so some maritime/air payloads (edge snapshots,
30:  * durable AIS caches) arrive carrying only the triple and no flat position
31:  * field. Returning its middle point reports the server's own position; it is
32:  * never a fabricated one. Longer paths are corridors, not fixes.
33:  */
34: export function getVehicleFix(vehicle: FleetVehicle): [number, number] | null {
35:   const currentCoords = asLonLat((vehicle as { current_coords?: unknown }).current_coords);
36:   if (currentCoords) return currentCoords;
37: 
38:   const currentLocation = asLonLat(
39:     (vehicle as { current_location?: { coordinates?: unknown } }).current_location?.coordinates,
40:   );
41:   if (currentLocation) return currentLocation;
42: 
43:   const location = (vehicle as { location?: unknown }).location;
44:   const locationCoords = asLonLat(
45:     Array.isArray(location) ? location : (location as { coordinates?: unknown } | undefined)?.coordinates,
46:   );
47:   if (locationCoords) return locationCoords;
48: 
49:   // Fallback extraction for lat and lon (or latitude / longitude)
50:   const vAny = vehicle as any;
51:   const lon = vAny.lon ?? vAny.longitude;
52:   const lat = vAny.lat ?? vAny.latitude;
53:   if (typeof lon === 'number' && typeof lat === 'number' && Number.isFinite(lon) && Number.isFinite(lat)) {
54:     return [lon, lat];
55:   }
56: 
57:   // Server-reported [prev, curr, next] path triple with no flat position
58:   // field: path[1] is the current fix by the backend's own invariant pass.
59:   const path = (vehicle as { path?: unknown }).path;
60:   if (Array.isArray(path) && path.length === 3) {
61:     const mid = asLonLat(path[1]);
62:     if (mid) return mid;
63:   }
64: 
65:   return null;
66: }
