101: export interface TrackingPartition {
102:   live: FleetVehicle[];
103:   projected: FleetVehicle[];
104: }
105: 
106: /** Splits a fleet into LIVE_GPS and ROUTE_ESTIMATED buckets. */
107: export function partitionByTracking(vehicles: FleetVehicle[]): TrackingPartition {
108:   const live: FleetVehicle[] = [];
109:   const projected: FleetVehicle[] = [];
110:   for (const v of vehicles) {
111:     if (isProjected(v)) projected.push(v);
112:     else if (isLiveTracked(v)) live.push(v);
113:   }
114:   return { live, projected };
115: }
