117: /**
118:  * Everything the dispatcher is allowed to see in the fleet workspace.
119:  * `live` is map-bound; `projected` is roster/inspection-only (PROYEKSI badge).
120:  */
121: export function scopeDispatcherFleet(
122:   vehicles: FleetVehicle[],
123:   companyId?: string | null
124: ): TrackingPartition & { all: FleetVehicle[] } {
125:   const all = selectTenantVehicles(vehicles, companyId);
126:   const { live, projected } = partitionByTracking(all);
127:   return { all, live, projected };
128: }

