    try {
      map.off('mouseenter', 'fleet-vehicle-dots', onMouseEnter);
      map.off('mousemove', 'fleet-vehicle-dots', onMouseMove);
      map.off('mouseleave', 'fleet-vehicle-dots', onMouseLeave);
      map.off('click', 'fleet-vehicle-dots', onClick);
